S.append(S2(c,B+' · 1','Ba kiểu học',card('Nhận ra qua dữ liệu',T(tr('Kiểu','Dấu hiệu',h=True)+tr('<b>Có giám sát</b>','mỗi mẫu <b>có nhãn</b> (10 000 ảnh gán “mèo/chó”)')+tr('<b>Không giám sát</b>','<b>không nhãn</b>; tìm cấu trúc ẩn, <b>phân cụm</b> khách hàng')+tr('<b>Tăng cường</b>','tác tử thử – nhận <b>phần thưởng</b> (tối đa hoá thưởng)'))),KEY('Có nhãn → giám sát; chia nhóm không nhãn → <b>không giám sát</b>.')))
S.append(S2(c,B+' · 1','Phân loại hay hồi quy?',card('Đầu ra quyết định',P('<b>Phân loại</b>: nhãn là <b>lớp rời rạc</b> (mèo/chó, spam/không).','<b>Hồi quy</b>: nhãn là <b>số liên tục</b> (điểm thi, giá nhà).','Cả hai đều là học <b>có giám sát</b>; <b>phân cụm</b> là không giám sát.')),T(tr('Bài toán','Loại',h=True)+tr('Lọc thư rác','phân loại')+tr('Dự đoán điểm thi từ số giờ ôn','hồi quy')+tr('Chia khách thành nhóm','phân cụm'))))
S.append(S2(c,B+' · 2','k-NN: bỏ phiếu theo láng giềng',card('Ý tưởng',STEPS(['Tính <b>khoảng cách</b> từ điểm mới tới mọi điểm huấn luyện (Euclid).','Chọn <b>k điểm gần nhất</b>.','<b>Bỏ phiếu đa số</b> nhãn của k điểm đó.']),P('k-NN <b>không có giai đoạn huấn luyện lâu</b>: chỉ lưu dữ liệu, tính khoảng cách khi dự đoán.')),KEY('Khoảng cách Euclid: <b>√((x₁−x₂)² + (y₁−y₂)²)</b>.')))
S.append(PR('2','Bài mẫu: dự đoán nhãn cho (4,4)',"import math\nA=[(1,1),(2,1),(1,2),(3,3)]\nB=[(6,5),(7,7),(6,6)]\npts=[(p,'A') for p in A]+[(p,'B') for p in B]\nq=(4,4)\nds=sorted((math.dist(p,q),l,p) for p,l in pts)\nfor d,l,p in ds[:4]: print(p,l,round(d,3))\nfor k in (1,3,7):\n    from collections import Counter\n    print('k=',k,Counter(l for _,l,_ in ds[:k]).most_common(1)[0][0])",P('Ba điểm gần nhất: (3,3) A, (6,5) B, (6,6) B.','<b>k=1</b> → A; <b>k=3</b> → B; <b>k=7</b> (toàn bộ) → A (4 A so với 3 B).'),'<b>Đổi k</b> có thể đổi kết quả.',16,22))
S.append(S2(c,B+' · 2','Chọn k thế nào?',card('Ảnh hưởng của k',T(tr('k','Hệ quả',h=True)+tr('<b>k = 1</b>','một điểm <b>nhiễu</b> gần nhất quyết định → dễ <b>quá khớp</b>')+tr('k lớn','mượt hơn, có thể bỏ sót chi tiết')+tr('k = số mẫu','luôn ra <b>lớp đa số</b>')),P('Thường chọn k <b>lẻ</b> để tránh hoà phiếu.')),KEY('k = 1 trên dữ liệu nhiễu: rủi ro <b>quá khớp</b>.')))
