S.append(PR('3','Bài mẫu: x = 1..5, y = 3; 5; 7; 9; 11,5',"xs=[1,2,3,4,5]; ys=[3,5,7,9,11.5]\nmx=sum(xs)/5; my=sum(ys)/5\nw=sum((x-mx)*(y-my) for x,y in zip(xs,ys))/sum((x-mx)**2 for x in xs)\nb=my-w*mx\nprint('w =',round(w,3),' b =',round(b,3))\nprint('y(6) =',round(w*6+b,2))",P('Điểm cuối 11,5 làm độ dốc <b>nhỉnh hơn 2,00</b>.','Dự đoán tại x = 6 khoảng <b>13,4</b>.'),'Đáp án: <b>w ≈ 2,10; y(6) ≈ 13,4</b>.',20,24))
