S.append(PR('4','Bài mẫu: k=2, tâm đầu (1,1) và (9,9)',"pts=[(1,1),(2,2),(1,3),(8,8),(9,7),(8,9)]\nc=[(1,1),(9,9)]\ncl=[[],[]]\nfor p in pts:\n    i=min((0,1),key=lambda j:(p[0]-c[j][0])**2+(p[1]-c[j][1])**2)\n    cl[i].append(p)\nnew=[(round(sum(x for x,_ in g)/len(g),2),round(sum(y for _,y in g)/len(g),2)) for g in cl]\nprint(cl)\nprint(new)",P('Ba điểm đầu thuộc cụm 1; ba điểm sau thuộc cụm 2.','Tâm mới: <b>(1,33; 2,00)</b> và <b>(8,33; 8,00)</b>.'),'Không nhầm thứ tự x, y.',17,22))
